function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };

  const O='#5a3a10', Gold='#e0a820', GoldLt='#f4d060', GoldDk='#b07818', Star='#fff0a0';
  for (let y=8;y<56;y++) for (let x=8;x<56;x++) {
    const dx=x-32, dy=y-32; if (dx*dx+dy*dy<=23*23) px(x,y,1,1,Gold);
  }
  for (let y=8;y<56;y++) for (let x=8;x<56;x++) {
    const dx=x-32, dy=y-32; const r=dx*dx+dy*dy;
    if (r<=23*23 && r>=20*20) px(x,y,1,1,O);
  }
  px(32,20,2,24,Star); px(20,32,24,2,Star);
  px(24,24,4,4,Star); px(36,24,4,4,Star);
  px(28,28,8,8,GoldDk);
}
